/**
 * @distilled.cloud/whop — Whop API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * in `.generated-specs` (written by `scripts/convert.ts` from the two
 * OpenAPI documents `scripts/download-spec.ts` downloads into `specs/`).
 * `./api-version.ts` is generated too — the dated version pin, read straight
 * off the spec. Everything else in this folder is hand-written.
 *
 * ## One surface, two references
 *
 * Whop documents one HTTP API through two reference sites, each with its own
 * OpenAPI document, and this SDK merges them into one client:
 *
 *   • the VERSIONED reference (`/api-reference/beta`) — accounts, plans,
 *     payouts, transfers, cards, bounties, ads, apps;
 *   • the LEGACY reference (`/api-reference`) — courses, forums, messages,
 *     invoices, refunds, affiliates, payment methods.
 *
 * Neither is a superset of the other. Where BOTH describe a route the
 * versioned one wins, so `Services.plans.listPlans` is always the current
 * generation. Operations that exist only on the legacy surface are still
 * generated — Whop supports them — and their doc comment opens with
 * `[Legacy API]` so a resource served by both (payments, memberships,
 * disputes) says which generation each call belongs to.
 *
 * ## Operation names
 *
 * Every operation is exported under its `operationId` from Whop's own
 * reference, verbatim — so a call here is greppable against the docs and the
 * MCP server. Whop is not consistent about pluralizing them (`listPlans` and
 * `listAccounts`, but `listPayment` and `listInvoice`), and neither is this
 * SDK: renaming would invent names that appear in none of Whop's own
 * material. Check the module's exports, or the resource's reference page.
 *
 * ## Files
 *
 * Uploads are presigned, not multipart: `Services.files.createFile` returns
 * an `upload_url` (or `multipart_upload_urls`) to PUT the bytes to, and the
 * resulting file `id` is what you attach elsewhere. The one endpoint whose
 * spec also offers a `multipart/form-data` body — `uploadDisputeEvidence` —
 * generates from its JSON variant, so attach evidence by `id` /
 * `direct_upload_id`; its `documents[].file` member only carries a value in
 * the multipart variant this SDK does not send.
 *
 * ## Versioning
 *
 * Whop pins request and response SHAPES to a date. Every call sends
 * {@link API_VERSION_DATE} — the version these schemas were generated from —
 * because an unpinned request falls back to the original `2025-01-01` shapes,
 * which is not what the generated schemas decode. Override it per client
 * through `credentials({ apiVersionDate })` only to reproduce older behavior.
 *
 * @example
 * ```ts
 * import * as Whop from "@distilled.cloud/whop";
 *
 * const plan = yield* Whop.Services.plans.createPlan({
 *   account_id: "biz_XXXXXXXX",
 *   product_id: "prod_XXXXXXXX",
 *   plan_type: "renewal",
 *   currency: "usd",
 *   // Safe to retry: the same key replays the stored response for 24h.
 *   idempotency_key: crypto.randomUUID(),
 * });
 * ```
 *
 * @example Streaming every page of a list
 * ```ts
 * import * as Stream from "effect/Stream";
 *
 * yield* Whop.Services.payments.listPayment.items({ first: 100 }).pipe(
 *   Stream.runForEach((payment) => Console.log(payment.id)),
 * );
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  WhopProtocol,
  type WhopOpError,
  type WhopOpContext,
} from "./protocol.ts";
export { paginateRelay } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
